def finding(row):
    fid,name,desc,kind,refs,vkind,req=row
    return {"id":fid,"name":name,"description":desc,"source_refs":refs,"questions":[{"id":f"{fid}-q01","text":f"What exact values, references, codes, scales, qualifiers and explicit unknowns must be recorded for {name.lower()}?","kind":kind,"answer_data":["value or typed reference","authority and version","status and valid time","explicit unknowns"]},{"id":f"{fid}-q02","text":f"Which learner, institution, registrar, assessor, awarding or recognizing authority and evidence establishes {name.lower()}, at what event and knowledge time, and with what confidence?","kind":"evidence","answer_data":["actor and role","authority and source","evidence","times","confidence"]},{"id":f"{fid}-q03","text":f"How may {name.lower()} be validated, appealed, corrected, superseded, revoked, retained or disclosed without erasing prior assertions or importing a neighboring lifecycle?","kind":"validation","answer_data":["validation rule","appeal or correction route","successor or tombstone","access and retention effect"]}],"data_elements":[{"id":f"{fid}-data","name":f"{name} data","description":f"Structured, source-qualified answer data for {name.lower()}.","value_kind":vkind,"cardinality":"1" if req else "0..n","required":req,"source_refs":refs}],"artifacts":[{"id":f"{fid}-record","name":f"{name} record","description":f"Versioned evidence-bearing record for {name.lower()} with learner binding, authority, event and knowledge time, provenance and access marking.","media_or_form":["logical education record","signed or attributable evidence reference"],"serial":True,"identity_strategy":f"Learner-record identifier plus {fid} assertion or event identifier; names, dates, grades, codes, filenames and hashes never identify the learner or award alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    return {"bundles":[{"id":bid,"name":n,"description":d,"rationale":r,"source_refs":refs,"layers":[{"id":lid,"name":ln,"description":ld,"source_refs":lr,"findings":[finding(x) for x in fs]} for lid,ln,ld,lr,fs in ls]} for bid,n,d,r,refs,ls in BUNDLES]}

