def service_layers():
    return {"dimension":{"owner_package_requirements":["Dimension identity, owner, learner-record steward, registrar, awarding authority and namespace","Person, institution, programme, course, activity, assessment, competency, occupation, credential, consent, evidence and decision registries","Master-system mappings for learner, programme, enrolment, result, award, credential, recognition and lifecycle-event identifiers","Classification, credit, grading, award, recognition, privacy, sealed-record, retention, federation and autonomous-agent policies"],"namespace_guidance":"Mint learner-record, award and assertion identifiers in the adopting Dimension only when no authoritative registrar or awarding-body identifier exists; preserve people, institutions, programmes, components, assessments, skills, occupations, licences, credentials, consents and evidence as typed references.","registry_links":["https://ver.cy/models/","https://ver.cy/model-agent-protocol.md","Dimension-local programme, enrolment, outcome, award, credential, recognition and provenance registries"]},"canon_and_patch":{"canonicalization_rules":["Canonicalize programmes, qualifications, learner records, awards and credentials by their own authoritative master-system identifiers and issuers, never by title, learner name, grade, date or hash alone.","Keep participation, attendance, completion, achievement, qualification definition, personal award, credential, recognition and professional authorization lifecycles distinct."],"patch_rules":["Additive extensions declare target bundle, layer or finding, education and jurisdiction profile, source, authority, privacy and interoperability impact.","Identity, rule, framework, scale, credit, award, subject-binding, status or recognition-semantic changes require a successor version, migration map, rollback and continued resolution of prior records."],"compatibility_rules":["Consumers may ignore unknown additive fields only when learner binding, authority, rules, framework, scale, evidence, award, credential status, privacy and provenance remain intact.","ISCED, EQF, national framework, ESCO, CTDL, CLR, Open Badges and VC mappings pin source and target versions and disclose transformed, omitted or non-round-trippable values."]},"artifact_rules":{"identity_priority":["Authoritative master-system identifier for the programme, award, credential or recognition record, qualified by issuer.","Governed globally resolvable IRI with explicit registrar or awarding-body binding.","Adopting-Dimension UUID or ULID when no authoritative external identifier exists."],"timestamp_rule":"Record events in RFC 3339 with seconds and explicit UTC offset or Z; keep learning, assessment, decision, conferral, issue, revocation, verification and ingestion times distinct.","serial_naming_rule":"Name serial artifacts as {learner-record-id}--{artifact-kind}--{assertion-or-event-id}; never use learner name, title, grade, date, filename or hash alone as identity.","integrity_rule":"Store digest, media type, byte length, issuer, source and profile versions, authority, event and knowledge times, provenance, assurance, licence and access marking for every retained serial artifact."},"policies":["The adopting Dimension declares who may register programmes, enrol learners, validate results, confer awards, issue credentials, recognize qualifications, disclose records, correct and revoke.","Participation, completion, achievement, qualification, award, credential, recognition and professional authorization are non-equivalent and cannot be inferred from each other without evidence.","Original grades, credits, scales, framework levels and terminology are preserved before any mapped value, and mappings never imply automatic equivalence.","Learners receive lawful access, portability, correction and disclosure control while registrars and awarding bodies retain source custody and statutory duties.","Automated agents may validate, map and assemble within policy; award, adverse correction, revocation, recognition and wider disclosure require accountable authority."],"crud":{"read":["Resolve active Dimension, learner and role, purpose, source masters, valid and knowledge time, credential status and access scope; return minimum necessary education claims."],"create":["Create stable identities, learner and authority references, source provenance, framework and rule versions and explicit unknowns before participation, outcome or award claims."],"update":["Append assertion, decision, mapping or successor with actor, authority, reason, RFC 3339 time, evidence and validation; never overwrite a cited result, award or credential."],"delete":["Apply learner rights, registrar duties, sealed-record, appeal, legal-hold, credential-status and retention policy; prefer restriction or tombstone and never cascade to external masters."]},"roles":[{"name":"Learner or lawful representative","responsibilities":["Exercise lawful access, portability, correction and disclosure choices and preserve contested claims."]},{"name":"Education provider or registrar","responsibilities":["Master programme participation, component results, transcript and correction records."]},{"name":"Assessor or validation body","responsibilities":["Assess evidence, moderate results and decide outcome achievement within authority."]},{"name":"Awarding body","responsibilities":["Own qualification rules and confer, correct or withdraw personal awards."]},{"name":"Credential issuer","responsibilities":["Issue accurate evidence, maintain status and protect subject binding and verification privacy."]},{"name":"Recognizing authority","responsibilities":["Make purpose and jurisdiction-specific comparability or recognition decisions with appeal."]},{"name":"Privacy and records steward","responsibilities":["Apply learner access, sealed-record, minimum disclosure, retention and audit rules."]},{"name":"Independent auditor","responsibilities":["Review authority, evidence, mappings, awards, status and disclosure without changing source truth."]}],"access":{"default_rule":"Deny mutation and disclosure of learner identity, participation, grades, incomplete work, sealed records, awards and credentials unless active Dimension, role, purpose and field policy grant it; expose the minimum claim.","scopes":["bundle","layer","finding","artifact"],"exceptions":["Statutory, judicial, safeguarding or emergency access must cite authority, be purpose-bound, attributable and reviewable and must not erase original results, appeals or audit evidence."],"audit_requirements":["Log actor, calling agent, role, purpose, learner, programme, award and credential identities, action, policy, RFC 3339 timestamp, effective authority, disclosed fields, evidence and outcome."]},"agents_bootstrap":{"filename":"AGENTS.md","required_fields":["Name","Type","Specification URL","Storage type URL","Interface URL","Processes URL"],"read_order":["Read the nearest Dimension-owner AGENTS.md, learner identity, registrar, award, recognition, privacy, sealed-record, retention and federation policies.","Read this model AGENTS.md, pinned spec.yaml and required person, institution, programme, assessment, competency, occupation, credential, consent and evidence instructions before mutation or disclosure."]}}

